function notice(text = '', error = false) { $('notice').textContent = text; $('notice').dataset.error = error; }
async function api(path, body) {
  const response = await fetch(`/api/${path}`, { method: body === undefined ? 'GET' : 'POST', headers: body === undefined ? {} : { 'Content-Type': 'application/json', 'X-Nexe-Request': '1' }, body: body === undefined ? undefined : JSON.stringify(body) });
  const value = await response.json();
  if (!response.ok) { if (response.status === 401 && user) { user = null; login(); } throw new Error(value.error || 'No se pudo completar la operación'); }
  return value;
}
function button(label, action, id = '', secondary = false) { return `<button type="button" data-action="${action}" data-id="${esc(id)}"${secondary ? ' class="secondary"' : ''}>${esc(label)}</button>`; }
function input(name, label, type = 'text', value = '', required = true) { return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required ? 'required' : ''} maxlength="${type === 'password' ? 512 : 250}"></label>`; }
function textarea(name, label, value = '', required = false) { return `<label>${esc(label)}<textarea name="${name}" maxlength="20000" ${required ? 'required' : ''}>${esc(value)}</textarea></label>`; }
function select(name, label, items, required = true, value = '') { return `<label>${esc(label)}<select name="${name}" ${required ? 'required' : ''}><option value="">Selecciona…</option>${items.map(([id, text]) => `<option value="${esc(id)}" ${id === value ? 'selected' : ''}>${esc(text)}</option>`).join('')}</select></label>`; }
const cdProgramIds = () => new Set(data.programs.filter(p => p.kind === 'dayCentre').map(p => p.id));
const cdGroups = () => data.groups.filter(g => cdProgramIds().has(g.program_id));
const cdPeopleIds = () => new Set(data.memberships.filter(m => cdProgramIds().has(m.program_id)).map(m => m.person_id));
const peopleOptions = (cdOnly = false) => data.people.filter(p => !cdOnly || cdPeopleIds().has(p.id)).map(p => [p.id, `${p.number} · ${p.nom} ${p.cognoms}`]);
const familyOptions = () => data.families.map(f => [f.id, f.name]);
const programOptions = (activeOnly = false) => data.programs.filter(p => !activeOnly || p.active).map(p => [p.id, p.name]);
const groupOptions = (cdOnly = false, activeOnly = false) => data.groups.filter(g => (!cdOnly || cdProgramIds().has(g.program_id)) && (!activeOnly || (g.active && data.programs.find(p => p.id === g.program_id)?.active))).map(g => [g.id, `${g.name} · ${g.course}`]);
function table(headers, rows) { return `<div class="table-wrap"><table class="${['attendance','dayCentre','users'].includes(section)?'nexe-table':''}"><thead><tr>${headers.map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${headers.length}">Todavía no hay registros.</td></tr>`}</tbody></table></div>`; }
function modal(title, fields, save, submit = 'Desar') {
  $('dialog').classList.toggle('cd-modal',section==='reports'); $('fields').classList.toggle('cd-modal-body',section==='reports'); document.querySelector('.dialog-head').classList.toggle('cd-modal-hdr',section==='reports'); $('dialogTitle').textContent = title; $('fields').innerHTML = fields; $('formError').textContent = ''; $('submitEditor').textContent = submit; $('submitEditor').hidden = !save;
  if(section==='reports') { for(const label of $('fields').querySelectorAll('label'))label.classList.add('ff'); for(const grid of $('fields').querySelectorAll('.grid'))grid.classList.add('frow'); } editorSave = save; $('dialog').showModal();
}
$('closeDialog').addEventListener('click', () => { if (!saving) $('dialog').close(); });
$('dialog').addEventListener('cancel', event => { if (saving) event.preventDefault(); });
$('editor').addEventListener('submit', async event => {
  event.preventDefault(); if (!editorSave || saving) return; saving = true; $('submitEditor').disabled = true; $('closeDialog').disabled = true;
  try { const result = await editorSave(Object.fromEntries(new FormData($('editor')))); $('dialog').close(); await refresh(); notice('Canvis desats.'); if (result?.next) result.next(); }
  catch (e) { $('formError').textContent = e.message; }
  finally { saving = false; $('submitEditor').disabled = false; $('closeDialog').disabled = false; }
});
function login() {
  document.body.classList.add('login-body'); document.body.classList.remove('collapsed','menu-open'); $('sidebar').hidden=true; $('topbar').hidden=true; $('approvedPage').href='/approved/login.css'; authAppearance(false);
  $('content').innerHTML=`<form id="login" class="login-card"><img src="/assets/logo.png" alt="Logo NexeSocial"><h2>Benvingut de nou</h2><p class="login-subtitle">Gestió d'usuaris centralitzada</p><div class="input-group"><label for="loginEmail">Correu Electrònic</label><input id="loginEmail" name="email" type="email" required placeholder="Ex: admin@nexesocial.com" autocomplete="username"></div><div class="input-group"><label for="loginPassword">Contrasenya</label><input id="loginPassword" name="password" type="password" required maxlength="512" placeholder="••••••••" autocomplete="current-password"></div><button class="btn-login">Accedir al Sistema</button><div class="login-note"><p>Accés protegit del personal autoritzat</p></div></form>`;
  $('login').addEventListener('submit', async event => { event.preventDefault(); const submit=event.target.querySelector('button'); submit.disabled=true; try { user=await api('login',Object.fromEntries(new FormData(event.target))); notice(); await refresh(); } catch(e) { notice(e.message,true); submit.disabled=false; } });
}
