function renderNav() { const active=section==='personDetail'?'people':section==='familyDetail'?'families':section; $('nav').innerHTML=navItem('home')+navGroups.slice(0,3).map(groupMarkup).join('')+navItem('totals')+groupMarkup(navGroups[3]); syncNavVisibility(); function groupMarkup([key,label,icon,ids]) { const allowed=ids.filter(id=>!['users','audit'].includes(id)||user.role==='admin'); if(!allowed.length)return ''; const open=allowed.includes(active); return `<div class="nav-group ${open?'open':''}"><button class="nav-group-toggle ${open?'has-active':''}" data-nav-group="${key}" title="${label}" aria-label="${label}" aria-expanded="${open}">${approvedIcons[icon]}<span>${label}</span><svg class="toggle-arrow" viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg></button><div class="nav-sub">${allowed.map(navItem).join('')}</div></div>`; } }
